import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR 0013 — the stop decision: an eight-round characterization","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/adrs/0013-the-stop-decision.md","filePath":"vendored/graphopt/project/adrs/0013-the-stop-decision.md"}`),a={name:`graphopt/project/adrs/0013-the-stop-decision.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0013-—-the-stop-decision-an-eight-round-characterization" tabindex="-1">ADR 0013 — the stop decision: an eight-round characterization <a class="header-anchor" href="#adr-0013-—-the-stop-decision-an-eight-round-characterization" aria-label="Permalink to “ADR 0013 — the stop decision: an eight-round characterization”">​</a></h1><p>Status: measured, open. Series: <code>results_stop_policy.md</code> (r1–2) → <code>results_stop_advantage.md</code> (r6, self-posterior + actor-critic) → <code>results_stop_valuelabel.md</code> (r7, expected-yield labels) → <code>results_stop_calibrated.md</code> (r8, Platt/isotonic calibration) → <code>results_stop_isolated.md</code> (r9, the delivery outside the softmax — <code>GatedPlayer</code> + the <code>forced_action</code> engine hook).</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>Should the open-game player keep evaluating pending candidates or stop? The oracle ceiling is measured: <strong>+0.026 reward/ep and 4.3× yield-per-eval</strong> (3.75 evals vs the incumbent&#39;s ~15) — real, and unreachable so far.</p><h2 id="what-eight-rounds-eliminated" tabindex="-1">What eight rounds eliminated <a class="header-anchor" href="#what-eight-rounds-eliminated" aria-label="Permalink to “What eight rounds eliminated”">​</a></h2><table tabindex="0"><thead><tr><th>blocker</th><th>round</th><th>verdict</th></tr></thead><tbody><tr><td>features</td><td>r1–2</td><td>shared-softmax stop logit drowns; supervised head degenerates to never-stop (Bayes-rational under asymmetric costs)</td></tr><tr><td>credit</td><td>r6</td><td>per-step advantage (actor-critic <code>AdvantagePlayer</code>) rescues AP vs collapse — real mechanism gain</td></tr><tr><td>observability</td><td>r6</td><td>policy&#39;s own posterior (<code>open:self</code>) ≈0.33 solo AP vs oracle labels — signal exists at zero predictor cost</td></tr><tr><td>value labels</td><td>r7</td><td><code>open:vlabel</code> expected-yield columns real, but predictors miscalibrate in magnitude held-out</td></tr><tr><td>calibration</td><td>r8</td><td>Platt/isotonic fixes magnitude (log-loss 3–5×, ECE ≤0.05) — <strong>best headless gate: isotonic <code>useful-pool</code> 0.2929 @ 12.8 evals, 26 real stops</strong></td></tr><tr><td>delivery</td><td>r9</td><td>the isolated channel (<code>forced_action</code> + <code>GatedPlayer</code>) clears both bars honestly — <code>iso-head:isotonic</code> 0.2892/AP 0.2101 @ 26 real stops, seam-free; the fold twin never-stops. Shared-softmax hypothesis <strong>confirmed for delivery</strong> — residual is evidence (all clears are tail-trims)</td></tr></tbody></table><h2 id="the-residual-blocker-stated-exactly" tabindex="-1">The residual blocker (stated exactly) <a class="header-anchor" href="#the-residual-blocker-stated-exactly" aria-label="Permalink to “The residual blocker (stated exactly)”">​</a></h2><p>At calibrated probabilities the break-even rule <em>rationally drains</em> (cost asymmetry: missed useful −1.0 vs wasted eval −0.002). No serializable arm clears both bake bars (reward ≥0.273 ∧ AP ≥0.210). What remains missing is <strong>held-out discrimination</strong> — a predictor that ranks pending candidates above chance out-of-distribution — or a stop delivery outside the shared softmax (the recurring corruption channel: five feature families all collapse AP the same way).</p><h2 id="transfer" tabindex="-1">Transfer <a class="header-anchor" href="#transfer" aria-label="Permalink to “Transfer”">​</a></h2><p>The lesson generalizes beyond stop: any gated decision in the game needs (a) features that see the decision-relevant quantity, (b) credit assigned per-step, (c) calibrated magnitudes, (d) a delivery channel isolated from ranking logits. Rounds 1–8 are the measured map of which of those was actually the wall at each stage.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};